export const COMMAND_TABLE: readonly CommandRow[] = ROWS.map((row) => {
  const [name = "", arity, flags = "", first, last, step, categories = "", ...docs] =
    row.split("\t")
  const [summary = "", since = "", group = "", complexity = ""] = docs
  return [
    name,
    Number(arity),
    flags,
    Number(first),
    Number(last),
    Number(step),
    categories,
    summary,
    since,
    group,
    complexity,
  ]
})
